import{_ as e,o as t,c as a,ac as p}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十二届中央委员会第四次全体会议公报*（1985年9月16日）*","description":"","frontmatter":{"prev":{"text":"中国共产党十二届四中全会给黄克诚同志的致敬信","link":"./中国共产党十二届四中全会给黄克诚同志的致敬信"},"next":{"text":"全国代表会议简介","link":"../n/"}},"headers":[],"relativePath":"12/4/中国共产党第十二届中央委员会第四次全体会议公报.md","filePath":"12/4/中国共产党第十二届中央委员会第四次全体会议公报.md"}'),r={name:"12/4/中国共产党第十二届中央委员会第四次全体会议公报.md"};function n(o,_,s,i,c,l){return t(),a("div",null,[..._[0]||(_[0]=[p('<h1 id="中国共产党第十二届中央委员会第四次全体会议公报-1985年9月16日" tabindex="-1">中国共产党第十二届中央委员会第四次全体会议公报*（1985年9月16日）* <a class="header-anchor" href="#中国共产党第十二届中央委员会第四次全体会议公报-1985年9月16日" aria-label="Permalink to &quot;中国共产党第十二届中央委员会第四次全体会议公报*（1985年9月16日）*&quot;">​</a></h1><p>  中国共产党第十二届中央委员会第四次全体会议，1985年9月16日在北京举行。</p><p>  出席这次会议的，有中央委员一百八十八人，候补中央委员一百二十九人；列席会议的，有中央顾问委员会委员一百三十人，中央纪律检查委员会委员一百二十一人，不是上述三个委员会成员的中央党政军机关和各省、自治区、直辖市党委的主要负责同志四十人。会议由中央政治局常委胡耀邦、邓小平、赵紫阳、李先念、陈云同志主持。叶剑英同志因病未出席会议。</p><p>  全会决定，今年9月18日召开中国共产党全国代表会议。</p><p>  全会讨论并原则通过了《中共中央关于制定国民经济和社会发展第七个五年计划的建议（草案）》，决定将这个文件提请党的全国代表会议审议。</p><p>  全会讨论确定了关于进一步实现中央领导机构成员新老交替的原则。全会收到了一批老同志分别请求不再担任第十二届中央委员会委员和候补委员、中央顾问委员会委员、中央纪律检查委员会委员的信。全会高度评价这些老同志从党和人民利益出发，积极促进中央领导机构成员新老交替的表率行动，同意他们不再担任中央三个委员会成员的请求，并向党的全国代表会议报告。</p><p>  全会给叶剑英同志和黄克诚同志写了致敬信，在他们由于健康原因请求不再担任中央领导职务的时候，以全会的名义表达全党同志对他们的崇高敬意和亲切问候。</p><p>  全体会议之前，开了四天预备会议，就上述议题进行了充分的酝酿和认真的讨论。</p><p>  这次会议开得生动活泼，是一次团结的会议，成功的会议。</p>',9)])])}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
